export async function POST() {
  const created = { weeks: 0, bookings: 0, demos: 0, payments: 0, errors: [] as string[] };

  const weekMap = new Map<string, string>();
  for (const w of IMPORT_DATA.weeks) {
    try {
      const week = await prisma.week.upsert({
        where: { weekStart: new Date(w.weekStart) },
        update: {},
        create: { weekStart: new Date(w.weekStart), weekEnd: new Date(w.weekEnd) },
      });
      weekMap.set(w.weekStart, week.id);
      weekMap.set(w.id, week.id);
      created.weeks++;
    } catch (e) { created.errors.push("Week: " + String(e).slice(0, 80)); }
  }

  const bookingIdMap = new Map<string, string>();
  for (const b of IMPORT_DATA.bookings) {
    try {
      const existing = await prisma.booking.findUnique({ where: { calendarEventId: b.calendarEventId } });
      if (existing) { bookingIdMap.set(b.id, existing.id); continue; }
      const realWeekId = weekMap.get(b.weekStart || "") || weekMap.get(b.weekId || "");
      if (!realWeekId) { created.errors.push("No week: " + b.prospectName); continue; }
      const booking = await prisma.booking.create({
        data: {
          weekId: realWeekId, prospectName: b.prospectName,
          prospectEmail: b.prospectEmail || null, prospectPhone: b.prospectPhone || null,
          setterId: b.setterId || null, demoDate: new Date(b.demoDate),
          calendarEventId: b.calendarEventId, source: "auto",
        },
      });
      bookingIdMap.set(b.id, booking.id);
      created.bookings++;
    } catch (e) { created.errors.push("Booking " + b.prospectName + ": " + String(e).slice(0, 80)); }
  }

  for (const d of IMPORT_DATA.demos) {
    try {
      const realBookingId = bookingIdMap.get(d.bookingId);
      if (!realBookingId) continue;
      const existing = await prisma.demo.findUnique({ where: { bookingId: realBookingId } });
      if (existing) continue;
      const realWeekId = weekMap.get(d.weekStart || "") || weekMap.get(d.weekId || "");
      if (!realWeekId) continue;
      await prisma.demo.create({
        data: { bookingId: realBookingId, weekId: realWeekId, closerId: d.closerId, status: d.status },
      });
      created.demos++;
    } catch (e) { created.errors.push("Demo: " + String(e).slice(0, 80)); }
  }

  for (const p of IMPORT_DATA.payments) {
    try {
      const existing = await prisma.payment.findUnique({ where: { stripePaymentIntentId: p.stripePaymentIntentId } });
      if (existing) continue;
      await prisma.payment.create({
        data: {
          stripePaymentIntentId: p.stripePaymentIntentId,
          amountCents: p.amountCents, currency: "usd", status: "succeeded",
          paidAt: p.paidAt ? new Date(p.paidAt) : new Date(), isMonth1: true, customerName: p.customerName || null,
        },
      });
      created.payments++;
    } catch (e) { created.errors.push("Payment: " + String(e).slice(0, 80)); }
  }

  return NextResponse.json({
    success: true,
    message: `Imported ${created.weeks} weeks, ${created.bookings} bookings, ${created.demos} demos, ${created.payments} payments`,
    created, errors: created.errors.slice(0, 10),
  });
}
